import {initialState,type State,type Trip,type PreferenceDimension,type Intent,type StarterConversation,type StarterSearchFilters,type StarterSelectedOffer,type StarterRoundTripCombo,type StarterSuggestedItinerary,type StarterLeg,type Offer,type SeatSelection,type TicketTraveller,type RequestedCabin,type LotusmilesAppliedRedemption} from '@/lib/model';
