import {z} from 'zod';
const intent=intentSchema;
const seatSelectionSchema=z.object({seat:z.string().trim().min(2).max(4),cabin:z.enum(['business','economy','economy-saver']),zone:z.enum(['front','middle','rear']),position:z.enum(['Aisle','Window','Middle']),recommended:z.boolean().optional(),reason:z.string().max(300).optional()}).strip();
const ticketTravellerSchema=z.object({name:z.string().trim().min(2).max(100),accountHolder:z.boolean().optional(),seatSelection:seatSelectionSchema}).strip();
function parsedSeatSelection(value:unknown):SeatSelection|null{return value?seatSelectionSchema.parse(value):null;}
function parsedTravellers(value:unknown,count:number):TicketTraveller[]{if(!Array.isArray(value)||value.length!==count)throw new Error(`VALIDATION:Cần thông tin và ghế cho đủ ${count} hành khách.`);const parsed=value.map((item,index)=>{const result=ticketTravellerSchema.safeParse(item);if(!result.success)throw new Error(`VALIDATION:Hành khách ${index+1} chưa có thông tin hoặc ghế hợp lệ.`);return result.data;});const seats=parsed.map(x=>x.seatSelection.seat);if(new Set(seats).size!==seats.length)throw new Error('VALIDATION:Mỗi hành khách phải có một ghế khác nhau.');return parsed;}
function ensureDemoLotusmiles(s:State){s.profile.lotusTier??=LOTUSMILES_DEMO_DEFAULTS.tier;s.profile.lotusMilesBalance??=LOTUSMILES_DEMO_DEFAULTS.balance;s.profile.lotusMilesExpiring??=LOTUSMILES_DEMO_DEFAULTS.expiring;}
function requestedCabinFromText(text:string):RequestedCabin|null{const n=String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(/\b(thuong gia|business class|business)\b/.test(n))return 'business';if(/\b(pho thong|economy class|economy)\b/.test(n))return 'economy';return null;}
function lotusReasonFor(s:State,input:{passengers:number;flexibility?:string|null;requestedCabin?:RequestedCabin|null}){if(!s.profile.member)return null;const best=bestLotusmilesDemoBenefit(s.profile,input);if(!best?.available)return null;if(best.kind==='business-upgrade')return `Lotusmiles demo: có thể cân nhắc nâng hạng Business với ${best.milesCostPerTraveller.toLocaleString('en-AU')} dặm mẫu/người`;if(best.kind==='preferred-seat')return 'Lotusmiles demo: có quyền lợi chọn ghế ưu tiên minh họa';return `Lotusmiles demo: có thể đổi ${best.milesCostPerTraveller.toLocaleString('en-AU')} dặm mẫu/người cho hành lý bổ sung`; }
function synthetic(t:Intent){return retrieveSyntheticOffers(t)}
function evidenceFor(s:State,tripId?:string){return s.profile.personalize?s.preferenceEvidence:(tripId?s.preferenceEvidence.filter(e=>e.tripId===tripId):[]);}
function rankOffers(s:State,t:Intent,offers:Offer[],tripId?:string){const ranked=rankOffersForIntent(offers,t,evidenceFor(s,tripId),s.profile.personalize);const top=ranked[0];if(top){const reason=lotusReasonFor(s,{passengers:t.passengers,flexibility:top.flexibility,requestedCabin:(t as Trip).requestedCabin||null});if(reason)top.rankingReasons=[...(top.rankingReasons||[]).filter(x=>!x.startsWith('Lotusmiles demo:')),reason].slice(0,4);}return ranked;}
function makeOffers(t:Intent,s?:State,tripId?:string){const offers=synthetic(t).offers;return s?rankOffers(s,t,offers,tripId):offers}
function retrievalSummary(t:Intent){return synthetic(t).summary}
function hydrateSyntheticTrips(s:State){for(const trip of s.trips){const legacy=!trip.retrieval||trip.offers.some(o=>!o.source);if(legacy){const r=synthetic(trip);trip.offers=rankOffers(s,trip,r.offers,trip.id);trip.retrieval=r.summary;delete trip.aiRecommendation;}else trip.offers=rankOffers(s,trip,trip.offers,trip.id);}}
function recordEvidence(s:State,tripId:string,offerId:string,dimension:PreferenceDimension|null,source:'explicit'|'choice'|'filter'|'booking',note?:string){if(!dimension||!s.profile.personalize)return;const recent=s.preferenceEvidence.slice(-20).find(e=>e.tripId===tripId&&e.offerId===offerId&&e.dimension===dimension&&e.source===source);if(recent)return;s.preferenceEvidence.push({id:crypto.randomUUID(),tripId,offerId,dimension,created:new Date().toISOString(),source,note});s.preferenceEvidence=s.preferenceEvidence.slice(-120);}
function recordPatchEvidence(s:State,tripId:string,patch:Partial<Intent>){if(patch.budget!=null)recordEvidence(s,tripId,`filter:price:${Date.now()}`, 'price','filter','Budget/filter change');if(patch.transit!=null)recordEvidence(s,tripId,`filter:transit:${Date.now()}`,'transit','filter','Transit/filter change');if(patch.baggage!=null)recordEvidence(s,tripId,`filter:baggage:${Date.now()}`,'baggage','filter','Baggage/filter change');}
function candidateMetrics(c:StarterFlightCandidate){return {price:c.totalPriceAUD,duration:c.totalDurationMinutes,transit:c.transitMinutes,baggage:c.baggageKg,flexibility:c.flexibility};}
function recordStarterChoice(s:State,chosen:StarterFlightCandidate,alternatives:StarterFlightCandidate[]){recordEvidence(s,'starter',chosen.id,inferPreferenceFromChoice(chosen,alternatives.filter(x=>x.id!==chosen.id),candidateMetrics),'choice','Selected flight versus visible alternatives');}
function itineraryMetrics(i:StarterSuggestedItinerary){const legs=[i.outbound,...(i.return?[i.return]:[])];return {price:i.totalPriceAUD,duration:legs.reduce((sum,l)=>sum+durationMinutes(l.totalDurationText),0),transit:legs.reduce((sum,l)=>sum+l.transitMinutes,0),baggage:Math.min(...legs.map(l=>l.baggageKg)),flexibility:legs.map(l=>l.flexibility||'').join(' ')};}
function recordItineraryChoice(s:State,tripId:string,chosen:StarterSuggestedItinerary,alternatives:StarterSuggestedItinerary[],source:'choice'|'booking'='choice'){recordEvidence(s,tripId,chosen.id,inferPreferenceFromChoice(chosen,alternatives.filter(x=>x.id!==chosen.id),itineraryMetrics),source,'Selected itinerary versus available alternatives');}
function rankItineraries(s:State,t:Trip,items:StarterSuggestedItinerary[]){return rankByPersonalValue(items,itineraryMetrics,evidenceFor(s,t.id),s.profile.personalize,{budget:t.budget,transit:t.transit*60,baggage:t.baggage}).map(x=>x.item);}
async function consumeLlmQuota(owner:string){const minute=Math.floor(Date.now()/60000),day=new Date().toISOString().slice(0,10);const quota=await database().prepare(`INSERT INTO llm_limits(owner,minute,count,day,daily_count) VALUES (?,?,1,?,1)
 ON CONFLICT(owner) DO UPDATE SET minute=excluded.minute,count=CASE WHEN llm_limits.minute=excluded.minute THEN llm_limits.count+1 ELSE 1 END,day=excluded.day,daily_count=CASE WHEN llm_limits.day=excluded.day THEN llm_limits.daily_count+1 ELSE 1 END
 WHERE (llm_limits.minute!=excluded.minute OR llm_limits.count<6) AND (llm_limits.day!=excluded.day OR llm_limits.daily_count<100) RETURNING owner`).bind(owner,minute,day).first();if(!quota)throw new LlmError('LLM_USER_LIMIT','Bạn đã đạt giới hạn chat (6 lượt/phút hoặc 100 lượt/ngày). Vui lòng thử lại sau.',429);}
function ensureStarter(s:State):StarterConversation{if(!s.starter)s.starter={messages:[],draft:{},searchFilters:{},phase:'collecting',selectedOfferId:null,selectedOffer:null,selectedOutboundOffer:null,selectedReturnOffer:null,tripMode:'unspecified',dateMode:'fixed',activeLeg:'outbound',checkoutStage:'none'};s.starter.searchFilters??={};s.starter.phase??='collecting';s.starter.tripMode??='unspecified';s.starter.dateMode??='fixed';s.starter.activeLeg??='outbound';s.starter.checkoutStage??='none';if(s.starter.selectedOfferId&&!s.starter.selectedOffer){const c=getStarterFlightById(s.starter.selectedOfferId,s.starter.draft.passengers??1);if(c)s.starter.selectedOffer=selectedSnapshot(c);}if(!s.starter.selectedOutboundOffer&&s.starter.selectedOffer)s.starter.selectedOutboundOffer=s.starter.selectedOffer;return s.starter;}
function starterCandidate(s:State){const d=s.starter?.draft||{};return {...d,name:(d.name||`${d.from||'Trip'} → ${d.to||'Trip'}`).slice(0,70),budget:d.budget??100000,passengers:d.passengers??1,baggage:d.baggage??s.profile.baggage??23,transit:d.transit??24,seat:d.seat||s.profile.seat||'No preference'};}
function starterReady(s:State){return intent.safeParse(starterCandidate(s)).success;}
function normText(text:string){return text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
function affirmative(text:string){
 const n=normText(text);
 // Keep this deliberately narrow. `co chuyen nao ...?` is a search question, not a yes.
 return /^(co|duoc|ok|okay|yes|yep|dong y|uh|uhm|oke)$/.test(n)
  || /^(co|duoc|ok|okay|yes|dong y) (nhe|nha|a|di|luon)$/.test(n)
  || /^(co|duoc|ok|okay|yes|dong y) (hay )?(chon|lay|cho toi|chuyen sang) (chuyen|lua chon|option|cai) (nay|do|vua recommend|vua de xuat|tot nhat)$/.test(n)
  || /^(lay|chon|cho toi|chuyen sang) (chuyen|lua chon|option|cai) (nay|do|vua recommend|vua de xuat|tot nhat)$/.test(n)
  || /^(go with|take|choose|select) (this|that|the recommended|the best) (one|option|flight)?$/.test(n);
}
function negative(text:string){const n=normText(text);return /^(khong|khong can|thoi|no|nope|cancel|bo qua)$/.test(n);}
function confirmPendingIntentText(text:string){const n=normText(text);return affirmative(text)||/^(xac nhan|ap dung|luu thay doi|luu lai|confirm|confirm update|apply|apply change|save change)$/.test(n);}
function dismissPendingIntentText(text:string){const n=normText(text);return negative(text)||/^(giu hien tai|giu nhu cu|khong ap dung|dismiss|keep current|keep it)$/.test(n);}
function removeBudgetLimitText(text:string){const n=normText(text);return /^(bo|xoa|go) (gioi han )?ngan sach$/.test(n)||/^(khong|ko) (can )?gioi han ngan sach$/.test(n)||/^(ngan sach )?(khong gioi han|thoai mai|linh hoat)$/.test(n)||/^(remove|drop|clear|no) (the )?budget( limit)?$/.test(n)||/^(no budget limit|unlimited budget)$/.test(n);}
function wantsRoundTrip(text:string){const n=normText(text);return /\b(khu hoi|round trip|roundtrip|di ve|ve lai|return ticket|return flight)\b/.test(n);}
function wantsOneWay(text:string){const n=normText(text);return /\b(mot chieu|one way|oneway|chi chieu di|chi di|khong can chieu ve|khong can khu hoi|khong can ve|no return)\b/.test(n);}
function cheapestText(text:string){const n=normText(text);return /\b(re nhat|gia re nhat|cheapest|lowest price|tiet kiem nhat)\b/.test(n);}
function windowText(text:string){const n=normText(text);return /\b(trong khoang|khoang thoi gian|between|within|tu .* den|from .* to)\b/.test(n);}
function avoidChinaTransitText(text:string){const n=normText(text);return (/\b(transit|noi chuyen|diem dung|qua)\b/.test(n)&&/\b(khong|tranh|not|avoid)\b/.test(n)&&/\b(trung quoc|china|guangzhou|shanghai|xiamen|can|pvg|xmn)\b/.test(n))||/\b(khong phai trung quoc|not china|avoid china)\b/.test(n);}
function requireTransitText(text:string){const n=normText(text);return /\b(co transit|co noi chuyen|phai transit|phai noi chuyen|with transit|one stop|1 stop)\b/.test(n);}
function shortTransitText(text:string){const n=normText(text);return /\b(transit ngan|noi chuyen ngan|it transit|short transit|short connection)\b/.test(n);}
function moreBaggageText(text:string){const n=normText(text);return /\b(nhieu hanh ly hon|them hanh ly|nhieu kg hon|nhieu can hon|tang hanh ly|more baggage|extra baggage|more checked baggage)\b/.test(n);}
function nextBaggageKg(current:number){if(current<23)return 23;if(current<32)return 32;if(current<46)return 46;return 46;}
function whatNextText(text:string){const n=normText(text);return /^(roi gio sao|gio sao|tiep theo lam gi|sau do sao|what next|now what|then what)$/.test(n);}
function declinePaymentText(text:string){const n=normText(text);return /\b(chua thanh toan|khong thanh toan|de sau|theo doi gia|monitor|not pay now|pay later|track price)\b/.test(n);}
function paymentText(text:string){const n=normText(text);return /\b(thanh toan|dat ve|checkout|pay|book now|continue booking)\b/.test(n)&&!declinePaymentText(text);}
function applyTripPendingIntent(s:State,t:Trip){const pending=t.pendingIntent;if(!pending||pending.baseVersion!==t.version)throw new Error('VALIDATION:Đề xuất đã thay đổi. Hãy tải lại chuyến đi.');const current=Object.fromEntries(Object.keys(intentSchema.innerType().shape).map(k=>[k,(t as any)[k]]));const merged=intent.parse({...current,...pending.patch});Object.assign(t,merged,{version:t.version+1,offers:makeOffers(merged,s,t.id),retrieval:retrievalSummary(merged)});recordPatchEvidence(s,t.id,pending.patch);delete t.aiRecommendation;delete t.pendingIntent;return merged;}
function applyTripPatchNow(s:State,t:Trip,patch:Partial<Intent>){
 const current=Object.fromEntries(Object.keys(intentSchema.innerType().shape).map(k=>[k,(t as any)[k]]));
 const merged=intent.parse({...current,...patch});
 const routeOrDateChanged=['from','to','start','end'].some(k=>k in patch);
 Object.assign(t,merged,{version:t.version+1,offers:makeOffers(merged,s,t.id),retrieval:retrievalSummary(merged)});
 recordPatchEvidence(s,t.id,patch);
 delete t.aiRecommendation;
 delete t.pendingIntent;
 if(routeOrDateChanged){delete t.selectedOffer;delete t.selectedReturnOffer;t.suggestedItineraries=[];t.monitoringSuggestions=[];}
 return merged;
}
function compactIntentUpdateReply(patch:Partial<Intent>){
 const labels:Record<string,string>={from:'điểm đi',to:'điểm đến',start:'ngày đi',end:'ngày về',budget:'ngân sách',passengers:'số khách',baggage:'hành lý',transit:'nối chuyến',seat:'ghế',name:'tên chuyến'};
 const changed=Object.keys(patch).map(k=>labels[k]||k);
 return changed.length?`Đã cập nhật Travel Intent: ${changed.join(', ')}.`:'Đã cập nhật Travel Intent.';
}
function statusQuestion(text:string){const n=normText(text);return /\b(xong chua|xong roi chua|da xong chua|da doi chua|status|done yet|is it done)\b/.test(n);}
function selectionCommand(text:string){
 const n=normText(text);
 return /\b(chon|lay|book|select|choose|take)\b.*\b(chuyen|lua chon|option|cai|recommended|recommend|de xuat|nay|do|tot nhat)\b/.test(n)
  || /\b(cho toi|chuyen sang|go with)\b.*\b(chuyen|lua chon|option|cai|recommended|recommend|de xuat|nay|do|tot nhat)\b/.test(n)
  || /^(chuyen|lua chon|option|cai) (nay|do|vua recommend|vua de xuat)$/.test(n);
}
function clearSelectionIfIntentChanged(st:StarterConversation,patch:Partial<Intent>){const out=st.selectedOutboundOffer||st.selectedOffer,ret=st.selectedReturnOffer,total=(out?.totalPriceAUD||0)+(ret?.totalPriceAUD||0);let invalid=['from','to','start','end'].some(k=>k in patch);if(patch.baggage!=null&&((out&&out.baggageKg<patch.baggage)||(ret&&ret.baggageKg<patch.baggage)))invalid=true;if(patch.transit!=null&&((out&&out.transitMinutes>patch.transit*60)||(ret&&ret.transitMinutes>patch.transit*60)))invalid=true;if(patch.budget!=null&&patch.budget<100000&&total>0&&total>patch.budget)invalid=true;if(invalid){st.selectedOfferId=null;st.selectedOffer=null;st.selectedOutboundOffer=null;st.selectedReturnOffer=null;st.pendingSuggestion=undefined;st.lastSearch=undefined;st.outboundSearch=undefined;st.returnSearch=undefined;st.roundTripCombos=undefined;st.suggestedItineraries=undefined;st.lotusmilesRedemption=null;st.returnSuggestionPending=false;st.checkoutStage='none';st.activeLeg='outbound';st.phase='collecting';}}
function mergeSearchFilters(st:StarterConversation,q:StarterOfferQuery):StarterSearchFilters{
 const f:{[key:string]:unknown}={...(st.searchFilters||{})};
 for(const key of q.clearFilters||[])delete f[key];
 for(const key of ['maxPrice','maxTransit','minBaggage','directOnly','requireTransit','transitVia','excludeChina'] as const){const value=q[key];if(value!==undefined&&value!==null)f[key]=value;}
 if(q.sortBy)f.sortBy=q.sortBy;if(q.limit)f.limit=q.limit;
 st.searchFilters=f as StarterSearchFilters;return st.searchFilters;
}
function currentQuery(st:StarterConversation,requested=true):StarterOfferQuery{return {requested,maxPrice:st.searchFilters?.maxPrice??null,maxTransit:st.searchFilters?.maxTransit??null,minBaggage:st.searchFilters?.minBaggage??null,directOnly:st.searchFilters?.directOnly??null,requireTransit:st.searchFilters?.requireTransit??null,transitVia:st.searchFilters?.transitVia??null,excludeChina:st.searchFilters?.excludeChina??null,sortBy:st.searchFilters?.sortBy||'best',limit:st.searchFilters?.limit||3,clearFilters:[]};}
function addIsoDays(value:string,days:number){const d=new Date(value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);}
function buildStarterSearch(s:State,leg:StarterLeg='outbound'):Parameters<typeof searchStarterFlights>[0]|null{const st=s.starter,d=st?.draft,f=st?.searchFilters;if(!d?.from||!d?.to)return null;const isReturn=leg==='return',useWindow=st?.dateMode==='window'&&!!d.start&&!!d.end,selectedOut=st?.selectedOutboundOffer||st?.selectedOffer;const windowStart=useWindow?(isReturn&&selectedOut?addIsoDays(selectedOut.departureDate,1):d.start!):null;return {from:isReturn?d.to:d.from,to:isReturn?d.from:d.to,departureDate:useWindow?null:(isReturn?(d.end||null):(d.start||null)),windowStart,windowEnd:useWindow?(d.end||null):null,passengers:d.passengers??1,maxPrice:f?.maxPrice??(d.budget&&d.budget<100000?d.budget:null),maxTransit:f?.maxTransit??null,minBaggage:f?.minBaggage??d.baggage??null,directOnly:f?.directOnly??null,requireTransit:f?.requireTransit??null,transitVia:f?.transitVia??null,excludeChina:f?.excludeChina??null,sortBy:f?.sortBy||'best',limit:f?.limit||3,personalization:{enabled:s.profile.personalize,evidence:evidenceFor(s)}};}
function shortOffer(c:StarterFlightCandidate){const transit=c.stops===0?'bay thẳng':`${Math.round(c.transitMinutes/6)/10}h transit tại ${c.transitCity||c.transitAirport}`;return `**${c.id}** (${c.departureDate}) — AUD ${c.totalPriceAUD.toLocaleString()} · ${c.totalDurationText} · ${transit} · ${c.baggageKg}kg`;}
function selectedSnapshot(c:StarterFlightCandidate):StarterSelectedOffer{return {offerId:c.id,departureDate:c.departureDate,departureTime:c.departureTime,arrivalDate:c.arrivalDate,arrivalTime:c.arrivalTime,routing:c.routing,totalPriceAUD:c.totalPriceAUD,totalDurationText:c.totalDurationText,stops:c.stops,transitAirport:c.transitAirport,transitCity:c.transitCity,transitMinutes:c.transitMinutes,baggageKg:c.baggageKg,flightReference:c.flightReference,fareType:c.fareType,flexibility:c.flexibility,selectedAt:new Date().toISOString()};}
function itineraryFromOffers(outbound:StarterSelectedOffer,returnOffer:StarterSelectedOffer|null|undefined,source:'chat'|'monitoring'='chat'):StarterSuggestedItinerary{return {id:returnOffer?`${outbound.offerId}__${returnOffer.offerId}`:outbound.offerId,outbound,return:returnOffer||null,totalPriceAUD:outbound.totalPriceAUD+(returnOffer?.totalPriceAUD||0),source};}
function itineraryFlexibility(itinerary:StarterSuggestedItinerary){return [itinerary.outbound.flexibility,itinerary.return?.flexibility].filter(Boolean).join(' / ');}
function lotusForItinerary(s:State,itinerary:StarterSuggestedItinerary,passengers:number){return buildLotusmilesBusinessUpgrade(s.profile,{passengers,flexibility:itineraryFlexibility(itinerary),baseItineraryId:itinerary.id,directions:itinerary.return?2:1});}
function requireBusinessSeats(travellers:TicketTraveller[],redemption:LotusmilesAppliedRedemption|null){if(redemption&&travellers.some(t=>t.seatSelection?.cabin!=='business'))throw new Error('VALIDATION:Lotusmiles Business đã được áp dụng, hãy chọn ghế Business cho tất cả hành khách.');}
function applyLotusBalance(s:State,redemption:LotusmilesAppliedRedemption|null){if(redemption)s.profile.lotusMilesBalance=redemption.remainingBalance;}
function archiveStarterItineraries(st:StarterConversation,items:StarterSuggestedItinerary[]){const merged=[...(st.suggestedItineraries||[]),...items],deduped=new Map<string,StarterSuggestedItinerary>();for(const item of merged)deduped.set(item.id,item);st.suggestedItineraries=[...deduped.values()].slice(-12);}
function selectedTripItinerary(t:Trip):StarterSuggestedItinerary|null{return t.selectedOffer?itineraryFromOffers(t.selectedOffer,t.selectedReturnOffer,'chat'):null;}
function paymentNotification(s:State,itinerary:StarterSuggestedItinerary,travel:{from:string;to:string;passengers:number;seat:string;travellers:TicketTraveller[]},lotusmilesRedemption:LotusmilesAppliedRedemption|null=null){const label=itinerary.return?`${itinerary.outbound.offerId} + ${itinerary.return.offerId}`:itinerary.outbound.offerId,ticketId=crypto.randomUUID(),reference=`LIA-${ticketId.slice(0,8).toUpperCase()}`,primary=travel.travellers[0]?.seatSelection||null,total=itinerary.totalPriceAUD+(lotusmilesRedemption?.cashTaxesAUD||0),loyaltyText=lotusmilesRedemption?` · Lotusmiles ${lotusmilesRedemption.milesUsed.toLocaleString('en-AU')} dặm + AUD ${lotusmilesRedemption.cashTaxesAUD.toLocaleString('en-AU')} thuế`:'';s.notifications.unshift({id:crypto.randomUUID(),tripId:`completed:${ticketId}`,kind:'payment',text:`Thanh toán demo thành công · ${label} · tổng tiền mặt AUD ${total.toLocaleString('en-AU')}${loyaltyText}.`,read:false,ticket:{id:ticketId,reference,paidAt:new Date().toISOString(),status:'paid-demo',from:travel.from,to:travel.to,passengers:travel.passengers,seat:primary?.position||travel.seat,seatSelection:primary,travellers:travel.travellers,outbound:itinerary.outbound,return:itinerary.return||null,lotusmilesRedemption,totalPriceAUD:total}});return {ticketId,total};}
function completeStarterPayment(s:State,st:StarterConversation,travellers:TicketTraveller[]){const out=st.selectedOutboundOffer||st.selectedOffer,ret=st.selectedReturnOffer;if(!out)throw new Error('VALIDATION:Hãy chọn hành trình trước khi thanh toán.');const itinerary=itineraryFromOffers(out,ret,'chat'),travel=starterCandidate(s),requested=st.lotusmilesRedemption?.baseItineraryId===itinerary.id,redemption=requested?lotusForItinerary(s,itinerary,Number(travel.passengers||1)):null;if(requested&&!redemption)throw new Error('VALIDATION:Ưu đãi Lotusmiles này không còn đủ điều kiện hoặc số dư không đủ.');requireBusinessSeats(travellers,redemption);recordItineraryChoice(s,'starter',itinerary,st.suggestedItineraries||[],'booking');if(redemption)recordEvidence(s,'starter',itinerary.id,'miles','booking','Completed a Lotusmiles Business redemption');const paid=paymentNotification(s,itinerary,{from:String(travel.from||''),to:String(travel.to||''),passengers:Number(travel.passengers||1),seat:String(travel.seat||s.profile.seat||'No preference'),travellers},redemption);applyLotusBalance(s,redemption);delete s.starter;return {paid:true,total:paid.total,itineraryId:itinerary.id,lotusmilesRedemption:redemption};}
function completeTripPayment(s:State,t:Trip,itinerary:StarterSuggestedItinerary,travellers:TicketTraveller[],useLotusmiles=false){const choices=[...(t.suggestedItineraries||[]),...(t.monitoringSuggestions||[])],requested=useLotusmiles||t.lotusmilesRedemption?.baseItineraryId===itinerary.id,redemption=requested?lotusForItinerary(s,itinerary,t.passengers):null;if(requested&&!redemption)throw new Error('VALIDATION:Ưu đãi Lotusmiles này không còn đủ điều kiện hoặc số dư không đủ.');requireBusinessSeats(travellers,redemption);recordItineraryChoice(s,t.id,itinerary,choices,'booking');if(redemption)recordEvidence(s,t.id,itinerary.id,'miles','booking','Completed a Lotusmiles Business redemption');const paid=paymentNotification(s,itinerary,{from:t.from,to:t.to,passengers:t.passengers,seat:travellers[0]?.seatSelection?.position||t.seat,travellers},redemption);applyLotusBalance(s,redemption);s.trips=s.trips.filter(x=>x.id!==t.id);return {paid:true,total:paid.total,itineraryId:itinerary.id,tripClosed:true,lotusmilesRedemption:redemption};}
function completeDirectBookingPayment(s:State,t:Trip,offer:Offer,seat:string,extraBag:boolean,travellers:TicketTraveller[],useLotusmiles=false){recordEvidence(s,t.id,offer.id,inferPreferenceFromChoice(offer,t.offers.filter(x=>x.id!==offer.id),o=>({price:o.price,duration:o.hours*60,transit:o.transit*60,baggage:o.baggage,miles:o.miles,flexibility:o.flexibility})),'booking','Completed direct booking versus visible alternatives');const redemption=useLotusmiles?buildLotusmilesBusinessUpgrade(s.profile,{passengers:t.passengers,flexibility:offer.flexibility,baseItineraryId:offer.id,directions:2}):null;if(useLotusmiles&&!redemption)throw new Error('VALIDATION:Ưu đãi Lotusmiles này không còn đủ điều kiện hoặc số dư không đủ.');requireBusinessSeats(travellers,redemption);if(redemption)recordEvidence(s,t.id,offer.id,'miles','booking','Completed a Lotusmiles Business redemption');const ticketId=crypto.randomUUID(),reference=`LIA-${ticketId.slice(0,8).toUpperCase()}`,total=offer.price+(extraBag&&!redemption?65*t.passengers:0)+(redemption?.cashTaxesAUD||0),primary=travellers[0]?.seatSelection||null,loyaltyText=redemption?` · dùng ${redemption.milesUsed.toLocaleString('en-AU')} dặm Lotusmiles`:'';s.notifications.unshift({id:crypto.randomUUID(),tripId:`completed:${ticketId}`,kind:'payment',text:`Thanh toán demo thành công · ${offer.flight} · ${t.from} → ${t.to} · tổng tiền mặt AUD ${total.toLocaleString('en-AU')}${loyaltyText}.`,read:false,ticket:{id:ticketId,reference,paidAt:new Date().toISOString(),status:'paid-demo',from:t.from,to:t.to,start:t.start,end:t.end,passengers:t.passengers,seat:primary?.position||seat,seatSelection:primary,travellers,directOffer:offer,extraBag:extraBag&&!redemption,lotusmilesRedemption:redemption,totalPriceAUD:total}});applyLotusBalance(s,redemption);s.trips=s.trips.filter(x=>x.id!==t.id);return {paid:true,total,ticketId,tripClosed:true,lotusmilesRedemption:redemption};}
function monitoringSuggestions(s:State,t:Trip):StarterSuggestedItinerary[]{const f=t.searchFilters||{},limit=Math.max(1,Math.min(6,f.limit||3));if(t.selectedReturnOffer){const found=searchStarterRoundTrip({from:t.from,to:t.to,startDate:t.start,endDate:t.end,dateMode:'fixed',passengers:t.passengers,filters:{maxPrice:f.maxPrice??(t.budget<100000?t.budget:null),maxTransit:f.maxTransit??t.transit,minBaggage:f.minBaggage??t.baggage,directOnly:f.directOnly??null,requireTransit:f.requireTransit??null,transitVia:f.transitVia??null,excludeChina:f.excludeChina??null,sortBy:f.sortBy||'best',limit,personalization:{enabled:s.profile.personalize,evidence:evidenceFor(s,t.id)}},limit});return found.combos.map(c=>itineraryFromOffers(selectedSnapshot(c.outbound),selectedSnapshot(c.return),'monitoring')).filter(x=>x.id!==`${t.selectedOffer?.offerId}__${t.selectedReturnOffer?.offerId}`).slice(0,limit);}const result=searchStarterFlights({from:t.from,to:t.to,departureDate:t.start,passengers:t.passengers,maxPrice:f.maxPrice??(t.budget<100000?t.budget:null),maxTransit:f.maxTransit??t.transit,minBaggage:f.minBaggage??t.baggage,directOnly:f.directOnly??null,transitVia:f.transitVia??null,excludeChina:f.excludeChina??null,requireTransit:f.requireTransit??null,sortBy:f.sortBy||'best',limit,personalization:{enabled:s.profile.personalize,evidence:evidenceFor(s,t.id)}});const visible=result.exactMatches.length?result.exactMatches:result.nearbyMatches;return visible.map(c=>itineraryFromOffers(selectedSnapshot(c),null,'monitoring')).filter(x=>x.id!==t.selectedOffer?.offerId).slice(0,limit);}
function selectedObservedPrice(t:Trip){const out=t.selectedOffer,ret=t.selectedReturnOffer;if(!out)return null;const currentOut=getStarterFlightById(out.offerId,t.passengers),currentRet=ret?getStarterFlightById(ret.offerId,t.passengers):null;return (currentOut?.totalPriceAUD??out.totalPriceAUD)+(ret?(currentRet?.totalPriceAUD??ret.totalPriceAUD):0);}
function durationMinutes(text:string){const h=Number(text.match(/(\d+(?:\.\d+)?)\s*h/i)?.[1]||0),m=Number(text.match(/(\d+)\s*m/i)?.[1]||0);return Math.round(h*60+m);}
function whyNowForItinerary(s:State,t:Trip,itinerary:StarterSuggestedItinerary){const legs=[itinerary.outbound,...(itinerary.return?[itinerary.return]:[])],pseudo:Offer={id:itinerary.id,label:'Monitoring match',price:itinerary.totalPriceAUD,transit:Number((legs.reduce((sum,l)=>sum+l.transitMinutes,0)/60).toFixed(1)),hours:Number((legs.reduce((sum,l)=>sum+durationMinutes(l.totalDurationText),0)/60).toFixed(1)),baggage:Math.min(...legs.map(l=>l.baggageKg)),miles:0,flight:legs.map(l=>l.flightReference||l.offerId).join(' + '),score:100,source:'synthetic-demo-dataset'};return whyNowForOffer(pseudo,t,evidenceFor(s,t.id),s.profile.personalize);}
function fallbackSearchReply(result:StarterFlightSearchResult){
 if(result.routeRows===0)return 'Dataset demo hiện chưa có record cho route này, nên mình không thể tạo một chuyến giả. Bạn có thể thử route khác có trong dữ liệu.';
 if(result.exactMatches.length){const lines=result.exactMatches.slice(0,3).map((o,i)=>`${i+1}. ${shortOffer(o)}`).join('\n');return `Mình đã tìm xong. Lựa chọn phù hợp nhất theo các điều kiện hiện tại là ${shortOffer(result.exactMatches[0])}.\n\nTop lựa chọn:\n${lines}\n\nĐây là dữ liệu giả lập của prototype, không phải giá/tồn chỗ live của Vietnam Airlines.`;}
 if(result.nearbyMatches.length){const lines=result.nearbyMatches.slice(0,3).map((o,i)=>`${i+1}. ${shortOffer(o)}`).join('\n');return `Không có lựa chọn thỏa toàn bộ điều kiện vào đúng ngày ${result.requestedDate}. Ngày gần đó có:\n\n${lines}\n\nMình đề xuất lựa chọn đầu tiên. Bạn có muốn chuyển ngày đi sang ${result.nearbyMatches[0].departureDate} và chọn chuyến đó không?\n\nĐây là dữ liệu giả lập của prototype.`;}
 if(result.sameDateNearMisses.length){const n=result.sameDateNearMisses[0];return `Không có chuyến thỏa toàn bộ điều kiện vào đúng ngày ${result.requestedDate}. Lựa chọn gần nhất là ${shortOffer(n)}.\nKhông đạt vì: ${n.violations.join(' ')}\nCó thể nới nhỏ nhất bằng cách: ${n.relaxations.join(' ')}\n\nĐây là dữ liệu giả lập của prototype.`;}
 return `Dataset demo có route này nhưng không có record phù hợp với ngày/bộ lọc hiện tại. Mình sẽ không tự bịa chuyến bay. ${result.requestedDate?'Bạn có thể đổi ngày hoặc nới một điều kiện.':''}`;
}
function saveLastSearch(st:StarterConversation,text:string,result:StarterFlightSearchResult,leg:StarterLeg='outbound'){
 const visible=result.exactMatches.length?result.exactMatches:result.nearbyMatches.length?result.nearbyMatches:result.sameDateNearMisses;
 const snapshots=visible.slice(0,3).map(selectedSnapshot),saved={query:text,leg,requestedDate:result.requestedDate,exactMatchIds:result.exactMatches.map(x=>x.id),nearbyMatchIds:result.nearbyMatches.map(x=>x.id),nearMissIds:result.sameDateNearMisses.map(x=>x.id),recommendedOfferId:result.recommended?.id||null,offers:snapshots,filters:{...(st.searchFilters||{})},searchedAt:new Date().toISOString()};
 st.lastSearch=saved;if(leg==='outbound')st.outboundSearch=saved;else st.returnSearch=saved;
 const selectedOut=st.selectedOutboundOffer||st.selectedOffer;if(leg==='return'&&selectedOut)archiveStarterItineraries(st,snapshots.map(ret=>itineraryFromOffers(selectedOut,ret,'chat')));else if(leg==='outbound')archiveStarterItineraries(st,snapshots.map(out=>itineraryFromOffers(out,null,'chat')));
 st.activeLeg=leg;st.roundTripCombos=undefined;
 if(result.nearbyMatches.length){const best=result.recommended||result.nearbyMatches[0];st.pendingSuggestion={kind:'switch_departure',offerId:best.id,departureDate:best.departureDate,reason:'No exact-date match; nearest suitable alternative.',filters:{...(st.searchFilters||{})},created:new Date().toISOString()};st.phase='awaiting-confirmation';}
 else {st.pendingSuggestion=undefined;st.phase='searching';}
}
function selectedReply(st:StarterConversation){
 const out=st.selectedOutboundOffer||st.selectedOffer,ret=st.selectedReturnOffer;
 if(!out)return 'Bạn chưa chọn chuyến nào. Mình có thể tìm và xếp hạng các lựa chọn trước.';
 if(ret)return `Bạn đã chọn combo khứ hồi ${out.offerId} + ${ret.offerId}. Tiếp theo LIA ưu tiên hoàn tất thông tin hành khách và chuyển sang thanh toán.`;
 if(st.returnSuggestionPending)return `Bạn đã chọn chiều đi ${out.offerId}. Mình có thể tìm thêm chiều về để tạo combo khứ hồi, hoặc bạn có thể giữ hành trình một chiều.`;
 return `Bạn đang chọn ${out.offerId}. Tiếp theo là thông tin hành khách và thanh toán; nếu chưa muốn thanh toán, bạn có thể chuyển sang theo dõi giá.`;
}
function statusReply(st:StarterConversation){if(st.pendingSuggestion){const c=getStarterFlightById(st.pendingSuggestion.offerId,st.draft.passengers??1);return `Mình đã tìm xong và đang chờ xác nhận đổi ngày${c?` cho ${c.id}`:''}.`; }if(st.selectedReturnOffer)return 'Đã chọn đủ hai chiều. Bước tiếp theo là thông tin hành khách và thanh toán.';if(st.selectedOutboundOffer||st.selectedOffer)return st.returnSuggestionPending?'Đã chọn chiều đi. Bạn có thể thêm chiều về hoặc tiếp tục một chiều.':'Đã chọn chuyến. Bước tiếp theo là checkout; theo dõi giá chỉ dùng nếu bạn chưa muốn thanh toán.';if(st.lastSearch?.recommendedOfferId)return 'Mình đã tìm xong nhưng bạn chưa chọn phương án nào.';return 'Chưa có tìm kiếm hoàn chỉnh. Bạn hãy cho mình tuyến/ngày và yêu cầu tìm chuyến.';}
function reverseLegNote(st:StarterConversation){const from=st.draft.to,to=st.draft.from;if(!from||!to||!st.draft.end)return '';const count=getStarterRouteCount(from,to);return count>0?` Dataset có ${count} record cho chặng về ${from} → ${to}.`:` Dataset demo hiện chưa có record ${from} → ${to}.`;}
function markCheckoutReady(s:State,st:StarterConversation){st.checkoutStage='offer-payment';st.returnSuggestionPending=false;st.phase='selected';st.lastSearch=undefined;st.outboundSearch=undefined;st.returnSearch=undefined;st.roundTripCombos=undefined;const out=st.selectedOutboundOffer||st.selectedOffer,ret=st.selectedReturnOffer,total=(out?.totalPriceAUD||0)+(ret?.totalPriceAUD||0);if(!out)return;const text=ret?`Hành trình khứ hồi đã chọn · ${out.offerId} + ${ret.offerId} · tổng demo AUD ${total.toLocaleString()}. Mở LIA để hoàn tất thông tin hành khách và tiếp tục thanh toán.`:`Chuyến ${out.offerId} đã chọn · demo AUD ${total.toLocaleString()}. Mở LIA để hoàn tất thông tin hành khách và tiếp tục thanh toán.`;const existing=s.notifications.find(n=>n.tripId==='starter'&&!n.read);if(existing)existing.text=text;else if(s.profile.notifications)s.notifications.unshift({id:crypto.randomUUID(),tripId:'starter',text,read:false});}
function acceptSuggestion(st:StarterConversation){
 const p=st.pendingSuggestion;if(!p)return null;const c=getStarterFlightById(p.offerId,st.draft.passengers??1);if(!c)return null;
 const leg=st.activeLeg||'outbound';if(p.kind==='switch_departure'){if(leg==='return')st.draft.end=p.departureDate;else st.draft.start=p.departureDate;}
 if(leg==='return')st.selectedReturnOffer=selectedSnapshot(c);else {st.selectedOutboundOffer=selectedSnapshot(c);st.selectedOffer=st.selectedOutboundOffer;st.selectedOfferId=c.id;}
 st.searchFilters={...p.filters};st.pendingSuggestion=undefined;st.phase='selected';
 return p.kind==='switch_departure'?`Đã chọn phương án gần nhất và cập nhật ngày ${leg==='return'?'về':'đi'} sang ${p.departureDate}.`:'Đã chọn chuyến này.';
}
function selectRecommended(st:StarterConversation){const id=st.lastSearch?.recommendedOfferId;if(!id)return null;const c=getStarterFlightById(id,st.draft.passengers??1);if(!c)return null;const leg=st.activeLeg||'outbound';if(st.lastSearch?.nearbyMatchIds.includes(id)){st.pendingSuggestion={kind:'switch_departure',offerId:id,departureDate:c.departureDate,reason:'Recommended nearby-date option.',filters:{...(st.searchFilters||{})},created:new Date().toISOString()};return acceptSuggestion(st);}if(leg==='return')st.selectedReturnOffer=selectedSnapshot(c);else {st.selectedOutboundOffer=selectedSnapshot(c);st.selectedOffer=st.selectedOutboundOffer;st.selectedOfferId=id;}st.phase='selected';return leg==='return'?'Đã chọn chuyến về được đề xuất.':'Đã chọn chuyến đi được đề xuất.';}
function compactStarterSearchReply(result:StarterFlightSearchResult,leg:StarterLeg='outbound'){
 const label=leg==='return'?'chuyến về':'chuyến đi';
 if(result.routeRows===0)return `Mình chưa có dữ liệu demo cho ${label} trên tuyến này.`;
 if(result.exactMatches.length)return `Mình tìm thấy ${Math.min(result.exactMatches.length,3)} ${label} phù hợp. Chọn trực tiếp trên thẻ.`;
 if(result.nearbyMatches.length)return `Không có ${label} khớp đúng ngày ${result.requestedDate||''}. Mình đã đưa các lựa chọn gần nhất vào thẻ.`;
 if(result.sameDateNearMisses.length)return `Chưa có ${label} khớp toàn bộ điều kiện. Mình đã hiển thị lựa chọn gần nhất để bạn cân nhắc.`;
 return `Chưa có ${label} phù hợp với các điều kiện hiện tại. Hãy đổi ngày hoặc nới một điều kiện.`;
}
async function runStarterSearch(s:State,text:string,q:StarterOfferQuery,leg:StarterLeg='outbound'){const st=ensureStarter(s);mergeSearchFilters(st,q);const filters=buildStarterSearch(s,leg);if(!filters)return {reply:'Mình cần điểm đi và điểm đến trước khi tìm chuyến.',result:null};st.phase='searching';const result=searchStarterFlights(filters);saveLastSearch(st,text,result,leg);return {reply:compactStarterSearchReply(result,leg),result};}
function comboSnapshot(c:SearchRoundTripCombo):StarterRoundTripCombo{return {id:c.id,outbound:selectedSnapshot(c.outbound),return:selectedSnapshot(c.return),totalPriceAUD:c.totalPriceAUD,totalDurationMinutes:c.totalDurationMinutes,totalTransitMinutes:c.totalTransitMinutes,rankingScore:c.rankingScore};}
function runRoundTripSearch(s:State,text:string,q:StarterOfferQuery){const st=ensureStarter(s),d=st.draft;if(!d.from||!d.to||!d.start||!d.end)return {reply:'Mình cần tuyến và hai mốc ngày để ghép combo khứ hồi.',result:null};mergeSearchFilters(st,q);const f=st.searchFilters||{};const result=searchStarterRoundTrip({from:d.from,to:d.to,startDate:d.start,endDate:d.end,dateMode:st.dateMode||'fixed',passengers:d.passengers??1,filters:{maxPrice:f.maxPrice??(d.budget&&d.budget<100000?d.budget:null),maxTransit:f.maxTransit??null,minBaggage:f.minBaggage??d.baggage??null,directOnly:f.directOnly??null,requireTransit:f.requireTransit??null,transitVia:f.transitVia??null,excludeChina:f.excludeChina??null,sortBy:f.sortBy||'best',limit:f.limit||3,personalization:{enabled:s.profile.personalize,evidence:evidenceFor(s)}},limit:f.limit||3});st.tripMode='round-trip';st.activeLeg='outbound';st.pendingSuggestion=undefined;st.lastSearch=undefined;st.outboundSearch=undefined;st.returnSearch=undefined;st.roundTripCombos=result.combos.map(comboSnapshot);archiveStarterItineraries(st,st.roundTripCombos.map(c=>itineraryFromOffers(c.outbound,c.return,'chat')));st.phase='searching';if(result.combos.length)return {reply:`Mình đã ghép ${result.combos.length} combo khứ hồi phù hợp từ dataset. Chọn combo trực tiếp trên thẻ.`,result};if(!result.routeRowsReturn)return {reply:`Mình có dữ liệu chiều đi nhưng chưa có dữ liệu demo cho chiều về ${d.to} → ${d.from}.`,result};return {reply:'Chưa có combo khứ hồi thỏa toàn bộ điều kiện. Hãy nới ngân sách, hành lý, transit hoặc khoảng ngày.',result};}
